mapper.select:
SELECT r.*, s.name AS stationName
FROM vp_cycle_report r
LEFT JOIN station_info s ON r.station_id = s.id AND s.deleted = 0

    r.deleted = 0
    AND r.tenant_id = #{reqVO.tenantId}

        AND r.report_cycle = #{reqVO.reportCycle}


        AND r.station_id = #{reqVO.stationId}


        AND r.report_status = #{reqVO.reportStatus}


        AND r.stat_start_time >= #{reqVO.beginTime}


        AND r.stat_end_time <= #{reqVO.endTime}


ORDER BY r.create_time DESC

SELECT COUNT(*)
FROM enter_record
WHERE station_id = #{stationId}
AND deleted = 0
AND tenant_id = #{tenantId}
AND enter_time BETWEEN #{startTime} AND #{endTime}

SELECT COUNT(*)
FROM leave_record
WHERE station_id = #{stationId}
AND deleted = 0
AND tenant_id = #{tenantId}
AND leave_time BETWEEN #{startTime} AND #{endTime}

SELECT COUNT(*)
FROM in_park_status
WHERE station_id = #{stationId}
AND deleted = 0
AND tenant_id = #{tenantId}
AND status = '正常'
AND in_time <= #{endTime}

SELECT COALESCE(
SUM(CASE WHEN status = '识别成功' THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0),
0
)
FROM plate_identify
WHERE station_id = #{stationId}
AND deleted = 0
AND tenant_id = #{tenantId}
AND create_time BETWEEN #{startTime} AND #{endTime}

SELECT COALESCE(
SUM(CASE WHEN status = '已缴清' THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0),
0
)
FROM pay_check
WHERE station_id = #{stationId}
AND deleted = 0
AND tenant_id = #{tenantId}
AND check_time BETWEEN #{startTime} AND #{endTime}

SELECT COALESCE(
SUM(CASE WHEN status = '已关闭' THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0),
0
)
FROM abnormal_leave
WHERE station_id = #{stationId}
AND deleted = 0
AND tenant_id = #{tenantId}
AND identify_time BETWEEN #{startTime} AND #{endTime}

SELECT COALESCE(
SUM(CASE WHEN status = '正常记录' THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0),
0
)
FROM pass_record
WHERE station_id = #{stationId}
AND deleted = 0
AND tenant_id = #{tenantId}
AND pass_reason = 'ETC'
AND pass_time BETWEEN #{startTime} AND #{endTime}
